const fs = require('fs');
const path = require('path');

function createExpect(actual) {
  return {
    toBe(expected) {
      const aVal = (actual !== null && actual !== undefined && typeof actual === 'object' && typeof actual.toString === 'function' && !(actual instanceof Date)) ? actual.toString() : actual;
      const eVal = (expected !== null && expected !== undefined && typeof expected === 'object' && typeof expected.toString === 'function' && !(expected instanceof Date)) ? expected.toString() : expected;
      
      if (aVal !== eVal) {
        throw new Error(`Expected ${JSON.stringify(expected)} but got ${JSON.stringify(actual)}`);
      }
    },
    toEqual(expected) {
      const actStr = JSON.stringify(actual);
      const expStr = JSON.stringify(expected);
      if (actStr !== expStr) {
        throw new Error(`Expected ${expStr} but got ${actStr}`);
      }
    },
    toBeDefined() {
      if (actual === undefined) {
        throw new Error(`Expected value to be defined, but got undefined`);
      }
    },
    toContain(item) {
      if (Array.isArray(actual)) {
        if (!actual.includes(item)) {
          throw new Error(`Expected array ${JSON.stringify(actual)} to contain ${JSON.stringify(item)}`);
        }
      } else if (typeof actual === 'string') {
        if (!actual.includes(item)) {
          throw new Error(`Expected string "${actual}" to contain "${item}"`);
        }
      } else {
        throw new Error(`Target ${JSON.stringify(actual)} does not support toContain`);
      }
    },
    toBeGreaterThan(num) {
      if (actual <= num) {
        throw new Error(`Expected ${actual} to be greater than ${num}`);
      }
    },
    toBeGreaterThanOrEqual(num) {
      if (actual < num) {
        throw new Error(`Expected ${actual} to be greater than or equal to ${num}`);
      }
    },
    toBeLessThan(num) {
      if (actual >= num) {
        throw new Error(`Expected ${actual} to be less than ${num}`);
      }
    },
    toBeLessThanOrEqual(num) {
      if (actual > num) {
        throw new Error(`Expected ${actual} to be less than or equal to ${num}`);
      }
    },
    toHaveBeenCalled() {
      if (!actual || !actual.mock || actual.mock.calls.length === 0) {
        throw new Error(`Expected mock function to have been called`);
      }
    },
    toHaveBeenCalledTimes(count) {
      const calls = (actual && actual.mock) ? actual.mock.calls.length : 0;
      if (calls !== count) {
        throw new Error(`Expected mock function to be called ${count} times, but called ${calls} times`);
      }
    },
    toHaveBeenCalledWith(...expectedArgs) {
      if (!actual || !actual.mock || actual.mock.calls.length === 0) {
        throw new Error(`Expected mock function to have been called`);
      }
      const lastCall = actual.mock.calls[actual.mock.calls.length - 1];
      expectedArgs.forEach((exp, idx) => {
        const act = lastCall[idx];
        if (exp && typeof exp === 'object' && typeof exp.test === 'function') {
          if (!exp.test(act)) {
            throw new Error(`Expected arg ${idx} to match asymmetric matcher, but got ${JSON.stringify(act)}`);
          }
        } else if (JSON.stringify(exp) !== JSON.stringify(act)) {
          throw new Error(`Expected arg ${idx} to equal ${JSON.stringify(exp)}, but got ${JSON.stringify(act)}`);
        }
      });
    }
  };
}

createExpect.objectContaining = function(expectedObj) {
  return {
    test(actualObj) {
      if (typeof actualObj !== 'object' || actualObj === null) return false;
      return Object.keys(expectedObj).every(key => {
        const expVal = expectedObj[key];
        const actVal = actualObj[key];
        if (expVal && typeof expVal === 'object' && typeof expVal.test === 'function') {
          return expVal.test(actVal);
        }
        if (expVal && typeof expVal === 'object' && actVal && typeof actVal === 'object') {
          return createExpect.objectContaining(expVal).test(actVal);
        }
        return actVal === expVal;
      });
    }
  };
};

createExpect.stringContaining = function(expectedStr) {
  return {
    test(actualStr) {
      return typeof actualStr === 'string' && actualStr.includes(expectedStr);
    }
  };
};

async function runTestFiles(testFiles) {
  let totalSuites = testFiles.length;
  let passedSuites = 0;
  let totalTests = 0;
  let passedTests = 0;
  let failedTests = 0;

  console.log('\nRunning Jest Test Suite...\n');
  const startTime = Date.now();

  for (const file of testFiles) {
    const relativePath = path.relative(process.cwd(), file);
    const beforeAllFns = [];
    const afterAllFns = [];
    const beforeEachFns = [];
    const afterEachFns = [];
    const testsToRun = [];

    global.describe = (name, fn) => {
      fn();
    };

    global.beforeAll = (fn) => beforeAllFns.push(fn);
    global.afterAll = (fn) => afterAllFns.push(fn);
    global.beforeEach = (fn) => beforeEachFns.push(fn);
    global.afterEach = (fn) => afterEachFns.push(fn);

    global.test = global.it = (name, fn) => {
      testsToRun.push({ name, fn });
    };

    global.expect = createExpect;

    const activeMocks = [];
    global.jest = {
      fn(impl) {
        const mockFn = function(...args) {
          mockFn.mock.calls.push(args);
          mockFn.mock.instances.push(this);
          if (typeof impl === 'function') {
            return impl.apply(this, args);
          }
        };
        mockFn.mock = { calls: [], instances: [] };
        mockFn.mockImplementation = (fn) => { impl = fn; return mockFn; };
        mockFn.mockReturnValue = (val) => { impl = () => val; return mockFn; };
        mockFn.mockResolvedValue = (val) => { impl = async () => val; return mockFn; };
        return mockFn;
      },
      spyOn(obj, prop) {
        const orig = obj[prop];
        const mockFn = global.jest.fn(orig);
        mockFn.mockRestore = () => { obj[prop] = orig; };
        obj[prop] = mockFn;
        activeMocks.push(mockFn);
        return mockFn;
      },
      restoreAllMocks() {
        activeMocks.forEach(m => m.mockRestore && m.mockRestore());
        activeMocks.length = 0;
      },
      clearAllMocks() {
        activeMocks.forEach(m => {
          if (m.mock) {
            m.mock.calls = [];
            m.mock.instances = [];
          }
        });
      }
    };

    // Clear require cache for fresh execution
    delete require.cache[require.resolve(file)];

    try {
      require(file);
    } catch (err) {
      console.error(`\n FAIL  ${relativePath}`);
      console.error(`  Syntax / Load Error: ${err.stack}`);
      failedTests++;
      continue;
    }

    let suiteFailed = false;

    // Run beforeAll
    for (const fn of beforeAllFns) {
      await fn();
    }

    for (const t of testsToRun) {
      totalTests++;
      for (const fn of beforeEachFns) {
        await fn();
      }

      try {
        await t.fn();
        passedTests++;
      } catch (err) {
        suiteFailed = true;
        failedTests++;
        console.error(`\n FAIL  ${relativePath}`);
        console.error(`  ✕ ${t.name}`);
        console.error(`    ${err.stack}\n`);
      }

      for (const fn of afterEachFns) {
        await fn();
      }
    }

    // Run afterAll
    for (const fn of afterAllFns) {
      await fn();
    }

    if (!suiteFailed) {
      passedSuites++;
      console.log(` PASS  ${relativePath}`);
    }
  }

  const durationSec = ((Date.now() - startTime) / 1000).toFixed(2);

  console.log(`\nTest Suites: ${passedSuites} passed, ${totalSuites} total`);
  console.log(`Tests:       ${passedTests} passed, ${totalTests} total`);
  console.log(`Snapshots:   0 total`);
  console.log(`Time:        ${durationSec} s`);
  console.log(`Ran all test suites.\n`);

  if (failedTests > 0) {
    process.exit(1);
  } else {
    process.exit(0);
  }
}

function main() {
  const testsDir = path.join(process.cwd(), 'tests');
  if (!fs.existsSync(testsDir)) {
    console.error('Error: tests directory not found');
    process.exit(1);
  }

  const files = fs.readdirSync(testsDir)
    .filter(f => f.endsWith('.test.js'))
    .map(f => path.join(testsDir, f));

  runTestFiles(files);
}

module.exports = {
  createExpect,
  runTestFiles,
  main
};

if (require.main === module) {
  main();
}
